-- T-053 (migration 0016; H-018; PROPOSED D-110, D-111; TEST-011, TEST-027):
-- the spend ledger of live AI. Tenant rows (organization days,
-- reservations) are their organization's only (RLS, composite keys to a
-- proposal, analysis or import of the same organization); the deployment's
-- totals need a scoped transaction; only the worker writes, and only the
-- amounts and a settlement; a reservation opens unsettled at its
-- transaction's time, is settled once and then never changes; nobody
-- deletes; an organization day holds exactly what its reservations hold
-- (checked at commit). Concurrency is the Go tests' (internal/storage/
-- aispend). Disposable dt_test_* database only (scripts/run_db_tests.sh).
-- One transaction, rolled back. Generated by scripts/render_db_tests.py.
\set ON_ERROR_STOP 1
BEGIN;
CREATE FUNCTION pg_temp.fail(msg text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF current_setting('dt.collect', true) = 'on' THEN RAISE WARNING 'FAILED: %', msg;
  ELSE RAISE EXCEPTION 'FAILED: %', msg; END IF;
END $$;
CREATE FUNCTION pg_temp.must_fail(stmt text, state text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE got text; msg text;
BEGIN
  BEGIN
    EXECUTE stmt;
    RAISE EXCEPTION USING ERRCODE = 'P0099'; -- roll the unexpected success back
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE; msg := SQLERRM;
  END;
  IF got = 'P0099' THEN
    PERFORM pg_temp.fail(format('expected SQLSTATE %s but the statement succeeded: %s', state, stmt));
  ELSIF got <> state THEN
    PERFORM pg_temp.fail(format('expected SQLSTATE %s but got %s (%s) for: %s', state, got, msg, stmt));
  END IF;
END $$;
-- The statements run one after the other and the deferred checks run as
-- at commit; all of it is rolled back, and the outcome must be state.
CREATE FUNCTION pg_temp.must_fail_at_commit(stmts text[], state text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE got text; msg text; s text;
BEGIN
  BEGIN
    FOREACH s IN ARRAY stmts LOOP
      EXECUTE s;
    END LOOP;
    SET CONSTRAINTS ALL IMMEDIATE;
    RAISE EXCEPTION USING ERRCODE = 'P0099'; -- roll the unexpected success back
  EXCEPTION WHEN OTHERS THEN
    got := SQLSTATE; msg := SQLERRM;
  END;
  SET CONSTRAINTS ALL DEFERRED;
  IF got = 'P0099' THEN
    PERFORM pg_temp.fail(format('expected SQLSTATE %s at commit but it committed: %s', state, array_to_string(stmts, '; ')));
  ELSIF got <> state THEN
    PERFORM pg_temp.fail(format('expected SQLSTATE %s at commit but got %s (%s) for: %s', state, got, msg, array_to_string(stmts, '; ')));
  END IF;
END $$;
CREATE FUNCTION pg_temp.check(ok boolean, what text) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF ok IS NOT TRUE THEN PERFORM pg_temp.fail(what); END IF;
END $$;
GRANT EXECUTE ON FUNCTION pg_temp.fail(text), pg_temp.must_fail(text, text), pg_temp.must_fail_at_commit(text[], text),
  pg_temp.check(boolean, text) TO PUBLIC;
-- The INSERT of an open reservation of tenant A for proposal aip on day d.
CREATE FUNCTION pg_temp.reserve(id text, aip text, d text, amount bigint) RETURNS text LANGUAGE sql AS $$
  SELECT format('INSERT INTO twin.ai_spend_reservations(id,organization_id,day,role,model,ai_proposal_id,request_id,reserved_nano_usd) '
      'VALUES (%L,%L,%L,%L,%L,%L,%L,%s)', id, 'org_01M4YDQK00TA00000000000000', d, 'modeler', 'claude-opus-5-5', aip, 'req_01M4YDQK00TA00000000000001', amount)
$$;
GRANT EXECUTE ON FUNCTION pg_temp.reserve(text, text, text, bigint) TO PUBLIC;

